    "DifficultyScore": 1,
    "CognitiveLevel": "Understand",
    "CalculationItem": true,
    "ItemStyle": "single-select",
    "LOSTag": "F.5",
    "FormulaReference": "Affected volume = Protected-group applicants x (Benchmark approval rate - Actual approval rate) x Average loan size",
