    "CalculationItem": false,
    "ItemStyle": "single-select",
    "LOSTag": "F.1",
    "FormulaReference": "",
    "CommonTrapReference": "Secondhand-competence trap: relying on another party's testing or review to certify work beyond one's own current competence",
